import java.util.ArrayList;
import java.util.List;

public class ClaimOffice {

    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    private final PayoutCalculator payoutCalculator = new PayoutCalculator();

    public List<StepResult> run(Scenario scenario) {
        List<StepResult> results = new ArrayList<>();
        int earlierContracts = 0;
        for (Step step : scenario.steps()) {
            if (step instanceof ClaimStep claimStep) {
                results.add(new ClaimResult(payoutCalculator.payoutFor(claimStep.incident()), 0));
                continue;
            }
            QuoteStep quoteStep = (QuoteStep) step;
            QuoteAssessment assessment =
                    new QuoteAssessment(scenario.customer(), earlierContracts);
            results.add(new QuoteResult(premiumCalculator.premiumFor(quoteStep, assessment)));
            earlierContracts++;
        }
        return results;
    }
}
