/**
 * What the office pays out for an incident reported against a policy.
 *
 * A deductible applies per damage event, so each damaged item bears it separately.
 */
public class PayoutCalculator {

    private static final int DEDUCTIBLE = 100;

    public int payoutFor(Incident incident) {
        double payout = 0;
        for (Damage damage : incident.damages()) {
            payout += damage.amount() - DEDUCTIBLE;
        }
        return roundInOfficesFavour(payout);
    }

    private int roundInOfficesFavour(double payout) {
        return (int) Math.floor(payout);
    }
}
